#!/usr/bin/env python3
from pathlib import Path
import base64
import sys

RENDERER_B64 = ''
ASSETS_B64 = {'victory_final.png': '', 'pick_final.png': '', 'locked_final.png': '', 'timeout_final.png': '', 'splash_10_kratos.png': ''}

def decode_renderer():
    return base64.b64decode(RENDERER_B64).decode("utf-8")

def replace_between(text: str, start_marker: str, end_marker: str, replacement: str) -> str:
    start = text.find(start_marker)
    if start == -1:
        raise RuntimeError(f"start marker not found: {start_marker}")
    end = text.find(end_marker, start)
    if end == -1:
        raise RuntimeError(f"end marker not found: {end_marker}")
    return text[:start] + replacement + "\n\n" + text[end:]

def write_assets(root: Path):
    out = root / "ppsspp/assets/scbd/winner_asset_v057c4"
    out.mkdir(parents=True, exist_ok=True)
    for name, b64 in ASSETS_B64.items():
        (out / name).write_bytes(base64.b64decode(b64))

def patch_debug_overlay(root: Path):
    debug = root / "ppsspp/UI/DebugOverlay.cpp"
    if not debug.exists():
        raise FileNotFoundError(debug)
    text = debug.read_text(encoding="utf-8")
    if "WINNER FINAL V0.5.7C4" in text:
        return
    start_marker = "static Draw::Texture *g_scbdWinnerFinalTextures[4] = {nullptr, nullptr, nullptr, nullptr};"
    end_marker = "static void DrawSCBDBoneMapper(UIContext *ctx, const Bounds &bounds) {"
    text = replace_between(text, start_marker, end_marker, decode_renderer())
    debug.write_text(text, encoding="utf-8")

def update_build_info(root: Path):
    p = root / "PSP_LIVE_FLOGB_BUILD_INFO.txt"
    line = "V0.5.7C4 Final Dynamic Layer Polish Pass 1\n"
    if p.exists():
        cur = p.read_text(encoding="utf-8")
        if line.strip() in cur:
            return
        p.write_text(cur + line, encoding="utf-8")
    else:
        p.write_text(line, encoding="utf-8")

def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: apply_psp_live_flogb_v0_5_7c4.py <repo_root>")
    root = Path(sys.argv[1]).resolve()
    write_assets(root)
    patch_debug_overlay(root)
    update_build_info(root)
    print("Applied V0.5.7C4 Dynamic Layer Polish Pass 1")

if __name__ == "__main__":
    main()
